import { useState } from "react";
import {
  X,
  Phone,
  Mail,
  MessageCircle,
} from "lucide-react";
import type { Lead } from "@/types/lead.types";

const TOPBAR_HEIGHT = 64;

/* ================= HELPERS ================= */

function getInitials(name: string) {
  return name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase();
}

/* ================= COMPONENT ================= */

export function LeadDetailsDrawer({
  lead,
  isOpen,
  onClose,
}: {
  lead: Lead | null;
  isOpen: boolean;
  onClose: () => void;
}) {
  const [tab, setTab] = useState<
    "details" | "notes" | "activity" | "next"
  >("details");

  const [notes, setNotes] = useState("");

  if (!isOpen || !lead) return null;

  return (
    <div
      className="
        fixed right-0 bottom-0
        bg-white border-l shadow-2xl z-50
        flex flex-col
        w-full sm:w-[420px]
      "
      style={{
        top: `${TOPBAR_HEIGHT}px`,
        height: `calc(100vh - ${TOPBAR_HEIGHT}px)`,
      }}
    >
      {/* ================= STICKY HEADER ================= */}
      <div className="sticky top-0 z-10 bg-white border-b px-5 py-4 flex items-start justify-between">
        <div className="flex items-start gap-3">
          <div className="w-10 h-10 rounded-full bg-gray-100 flex items-center justify-center text-sm font-semibold">
            {getInitials(lead.name)}
          </div>
          <div>
            <p className="font-semibold leading-tight">{lead.name}</p>
            <p className="text-xs text-gray-500">{lead.email}</p>
          </div>
        </div>

        <button onClick={onClose} className="p-1">
          <X size={18} />
        </button>
      </div>

      {/* ================= STICKY STATUS ================= */}
      <div className="sticky top-[73px] z-10 bg-white border-b px-5 py-3">
        <select
          value={lead.status}
          className="w-full border rounded-lg px-3 py-2 text-sm"
        >
          <option value="Qualified">Qualified</option>
          <option value="Unqualified">Unqualified</option>
          <option value="Follow Up">Follow Up</option>
        </select>
      </div>

      {/* ================= STICKY ACTIONS ================= */}
      <div className="sticky top-[130px] z-10 bg-white border-b px-5 py-4 grid grid-cols-3 gap-3">
        <Action icon={<Phone size={16} />} label="Call" disabled />
        <Action icon={<Mail size={16} />} label="Email" />
        <Action icon={<MessageCircle size={16} />} label="WhatsApp" />
      </div>

      {/* ================= STICKY TABS ================= */}
      <div className="sticky top-[200px] z-10 bg-white border-b px-5 flex gap-4">
        {[
          ["details", "Details"],
          ["notes", "Notes"],
          ["activity", "Activity"],
          ["next", "Next Call"],
        ].map(([key, label]) => (
          <button
            key={key}
            onClick={() => setTab(key as any)}
            className={`py-3 text-sm ${
              tab === key
                ? "border-b-2 border-black font-semibold"
                : "text-gray-500"
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      {/* ================= SCROLLABLE CONTENT ================= */}
      <div className="flex-1 overflow-y-auto px-5 py-5 space-y-5 text-sm">
        {tab === "details" && (
          <>
            <InfoRow label="Phone" value={lead.phone} />
            <InfoRow label="Email" value={lead.email} />

            <div>
              <p className="text-gray-500 mb-1">Business Description</p>
              <p className="text-gray-700 leading-relaxed">
                {lead.business_description}
              </p>
            </div>
          </>
        )}

        {tab === "notes" && (
          <textarea
            placeholder="Add internal notes..."
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            className="w-full h-40 border rounded-lg p-3 text-sm resize-none"
          />
        )}

        {tab === "activity" && (
          <ul className="space-y-3 text-gray-600">
            <li>ΓÇó AI conversation completed</li>
            <li>ΓÇó Lead status: {lead.status}</li>
          </ul>
        )}

        {tab === "next" && (
          <div>
            <label className="text-gray-500 block mb-1">
              Schedule next call
            </label>
            <input
              type="datetime-local"
              className="border rounded-lg px-3 py-2 w-full text-sm"
            />
          </div>
        )}
      </div>

      {/* ================= STICKY FOOTER ================= */}
      <div className="border-t px-5 py-4 bg-white">
        <p className="text-xs text-gray-500 mb-2">Next Suggested Action</p>

        <div className="flex gap-3">
          <button className="flex-1 border rounded-lg py-2 text-sm">
            Schedule Call
          </button>
          <button className="flex-1 border rounded-lg py-2 text-sm">
            Send WhatsApp
          </button>
        </div>

        <div className="mt-3 text-xs text-gray-500">
          Last AI Call:{" "}
          <span className="text-gray-700">4m 32s ┬╖ {lead.status}</span>
        </div>
      </div>
    </div>
  );
}

/* ================= SUB COMPONENTS ================= */

function Action({
  icon,
  label,
  disabled,
}: {
  icon: React.ReactNode;
  label: string;
  disabled?: boolean;
}) {
  return (
    <button
      disabled={disabled}
      className={`border rounded-xl py-3 flex flex-col items-center gap-1 text-sm ${
        disabled
          ? "bg-gray-100 text-gray-400"
          : "hover:bg-gray-50"
      }`}
    >
      {icon}
      <span>{label}</span>
    </button>
  );
}

function InfoRow({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    <div className="flex justify-between">
      <span className="text-gray-500">{label}</span>
      <span className="font-medium">{value}</span>
    </div>
  );
}

import { createContext, useContext, useState } from "react";
import type { ReactNode } from "react";

type AuthContextType = {
  isAuthenticated: boolean;
  login: () => void;
  logout: () => void;
};

const AuthContext = createContext<AuthContextType | null>(null);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(
    () => localStorage.getItem("auth") === "true"
  );

  const login = () => {
    localStorage.setItem("auth", "true");
    setIsAuthenticated(true);
  };

  const logout = () => {
    localStorage.removeItem("auth");
    setIsAuthenticated(false);
  };

  return (
    <AuthContext.Provider value={{ isAuthenticated, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error("useAuth must be used inside AuthProvider");
  }
  return ctx;
};

import { useState } from "react";
import { Eye, EyeOff, AlertCircle } from "lucide-react";
import { useNavigate } from "react-router-dom";
import authApi from "@/api/authApi";

const LoginPage = () => {
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");


  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    if (!email || !password) {
      setError("Please enter your administrator credentials.");
      return;
    }

    try {
      setLoading(true);
      await authApi.login(email, password);
      navigate("/dashboard", { replace: true });
    } catch (err: any) {
      setError(
        err?.response?.data?.detail ||
        "Invalid email or password"
      );
    } finally {
      setLoading(false);
    }
};


  return (
    <div className="min-h-screen bg-gray-50 dark:bg-slate-900 flex items-center justify-center px-4">
      <div className="w-full max-w-md">
        {/* Header */}
        <div className="text-center mb-6">
          <h3
          className="
            text-xl md:text-2xl font-bold tracking-tighter mb-6
            bg-clip-text
            bg-gradient-to-b
            from-foreground to-foreground/60
          "
          >
            <img
              src="/voicedotslogo.svg"
              alt="V"
              className="h-[1.1em] w-auto inline-block align-middle -translate-y-[0.1em] mr-[-0.3em]"
            />oiceDots
          </h3>
          
          <h1 className="text-3xl font-extrabold text-gray-900 dark:text-white">
            Admin Portal
          </h1>

          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Secure access for authorized personnel only
          </p>
        </div>

        {/* Card */}
        <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-lg border border-gray-200 dark:border-slate-700 px-6 py-8 sm:px-8">
          <form  className="space-y-6" onSubmit={handleLogin}>
            {/* Error */}
            {error && (
              <div
                className="flex items-center gap-2 rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-800 dark:border-red-900 dark:bg-red-900/10 dark:text-red-400"
                role="alert"
              >
                <AlertCircle size={16} />
                {error}
              </div>
            )}

            {/* Email */}
            <div>
              <label
                htmlFor="email"
                className="block text-sm font-medium text-gray-700 dark:text-gray-200"
              >
                Email address
              </label>
              <input
                id="email"
                type="email"
                name="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                placeholder="admin@voicedots.com"
                className="mt-1 w-full rounded-lg border border-gray-300 px-4 py-3 text-sm focus:border-blue-500 focus:ring-blue-500 dark:bg-slate-900 dark:border-slate-700 dark:text-gray-200"
              />
            </div>

            {/* Password */}
            <div>
              <label
                htmlFor="password"
                className="block text-sm font-medium text-gray-700 dark:text-gray-200"
              >
                Password
              </label>

              <div className="relative mt-1">
                <input
                  id="password"
                  name="password"
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                  className="w-full rounded-lg border border-gray-300 px-4 py-3 pr-10 text-sm focus:border-blue-500 focus:ring-blue-500 dark:bg-slate-900 dark:border-slate-700 dark:text-gray-200"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-blue-600"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {/* Remember + Forgot */}
            <div className="flex items-center justify-between">
              <label className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-300">
                <input
                  type="checkbox"
                  className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 dark:border-slate-700"
                />
                Trust this device
              </label>

              <a
                href="#"
                className="text-sm font-medium text-blue-600 hover:text-blue-500 dark:text-blue-400"
              >
                Forgot password?
              </a>
            </div>

            {/* Submit */}
            <button
              type="submit"
              disabled={loading}
              className="w-full rounded-lg bg-blue-600 px-4 py-3 text-sm font-semibold tracking-wide text-white hover:bg-blue-700 disabled:opacity-50 transition"
            >
              {loading ? (
                <span
                  className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent"
                  aria-label="loading"
                />
              ) : (
                "Sign in to Dashboard"
              )}
            </button>

            {/* Divider */}
            <div className="relative pt-2">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-gray-200 dark:border-slate-700" />
              </div>
              <div className="relative flex justify-center">
                <span className="bg-white dark:bg-slate-800 px-2 text-xs text-gray-500">
                  Security Verified
                </span>
              </div>
            </div>
          </form>
        </div>

        {/* Footer */}
        <p className="mt-6 text-center text-xs text-gray-400 dark:text-gray-500">
          ┬⌐ 2026 Voicedots. All rights reserved.
        </p>
      </div>
    </div>
  );
};

export default LoginPage;

import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import {
  ArrowLeft,
  Loader2,
  User,
  Phone,
  Mail,
  Briefcase,
  AlertCircle,
  FileText,
  Clock,
  PhoneCall,
  X,
} from "lucide-react";
import conversationsApi from "@/api/conversations";
import { UI } from "@/ui/colors";
import type { GetConversationDetailsResult } from "@/types/conversation.types";
import { ConversationAudioPlayer } from "@/components/ConversationAudioPlayer";

const logoIcon = "/voicedotslogo.svg";

const formatTime = (timestamp?: number) => {
  if (!timestamp) return "";
  const date = new Date(timestamp > 1e10 ? timestamp : timestamp * 1000);
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
};

export function ConversationDetails() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [data, setData] = useState<GetConversationDetailsResult | null>(null);
  const [showMobileInfo, setShowMobileInfo] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string>("");

  useEffect(() => {
    async function fetchConversationDetails() {
      try {
        setIsLoading(true);
        if (id) {
          const response = await conversationsApi.getConversationDetails(id);
          setData(response);
          const audioBlob = await conversationsApi.getConversationAudio(id);
          const url = URL.createObjectURL(audioBlob);
          setAudioUrl(url);
        }
      } finally {
        setIsLoading(false);
      }
    }
    fetchConversationDetails();
  }, [id]);

  const lead = data?.lead;
  const messages = data?.transcription;

  return (
    <div className="h-full flex flex-col bg-white overflow-hidden">
      {/* BACK */}
      <div className="border-b px-4 py-3 shrink-0 flex justify-between items-center">
        <button
          onClick={() => navigate(-1)}
          className="flex items-center gap-2 text-sm text-gray-600"
        >
          <ArrowLeft size={16} />
          Back
        </button>

        {/* MOBILE INFO BUTTON */}
        <button
          onClick={() => setShowMobileInfo(true)}
          className="md:hidden text-sm font-medium text-blue-600"
        >
          Lead Info
        </button>
      </div>

      {/* TITLE */}
      <div className="border-b px-4 py-3 shrink-0 flex flex-col md:flex-row md:items-center md:justify-between gap-3">
        <div className="pl-3" style={{ borderLeft: `4px solid ${UI.colors.primary}` }}>
          <h1 className="text-lg md:text-xl font-bold">Transcript Details</h1>
          <p className="text-xs text-gray-500 font-mono truncate">
            ID: {id}
          </p>
        </div>

        <ConversationAudioPlayer audioUrl={audioUrl} />
      </div>

      {/* BODY */}
      <div className="flex-1 overflow-hidden">
        <div className="grid grid-cols-1 md:grid-cols-[1fr_260px] h-full">
          {/* CHAT */}
          <div className="overflow-y-auto px-4 md:px-6 py-4">
            <div className="max-w-4xl mx-auto space-y-6">
              <div className="flex justify-center">
                <span className="px-3 py-1 bg-gray-100 text-xs rounded-full">
                  Conversation Start
                </span>
              </div>

              {isLoading ? (
                <div className="flex justify-center py-20">
                  <Loader2 className="animate-spin" />
                </div>
              ) : (
                messages?.map((msg, i) => {
                  const isAgent = msg.role === "agent";
                  if (!msg.message) return null;

                  return (
                    <div
                      key={i}
                      className={`flex gap-3 ${
                        isAgent ? "flex-row" : "flex-row-reverse"
                      }`}
                    >
                      {isAgent ? (
                        <img src={logoIcon} className="w-9 h-9 rounded-full border p-1" />
                      ) : (
                        <div className="w-9 h-9 rounded-full bg-blue-100 flex items-center justify-center">
                          <User size={16} />
                        </div>
                      )}

                      <div className={`max-w-[80%]`}>
                        <div className="text-xs text-gray-500 mb-1">
                          {isAgent ? "SRK" : lead?.name || "User"} ┬╖{" "}
                          {formatTime(msg.timestamp)}
                        </div>

                        <div
                          className={`rounded-xl px-4 py-2 text-sm ${
                            isAgent
                              ? "bg-white border"
                              : "text-white"
                          }`}
                          style={{
                            backgroundColor: isAgent
                              ? undefined
                              : UI.colors.primary,
                          }}
                        >
                          {msg.message}

                          {msg.interrupted && (
                            <div className="flex items-center gap-1 mt-1 text-xs text-red-500">
                              <AlertCircle size={12} />
                              Interrupted
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>

          {/* DESKTOP SIDEBAR */}
          <aside className="hidden md:block border-l bg-gray-50 px-4 py-4">
            <LeadInfo lead={lead} />
          </aside>
        </div>
      </div>

      {/* MOBILE BOTTOM SHEET */}
      {showMobileInfo && (
        <div className="fixed inset-0 z-50 bg-black/40 md:hidden">
          <div className="absolute bottom-0 w-full bg-white rounded-t-xl p-4 max-h-[80vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-semibold">Lead Info</h3>
              <button onClick={() => setShowMobileInfo(false)}>
                <X />
              </button>
            </div>
            <LeadInfo lead={lead} />
          </div>
        </div>
      )}
    </div>
  );
}

/* ========== SHARED LEAD INFO ========== */

function LeadInfo({ lead }: any) {
  return (
    <div className="space-y-4">
      <div className="bg-white border rounded-lg">
        <div className="flex gap-3 px-4 py-3 border-b">
          <div className="w-9 h-9 rounded-full bg-blue-100 flex items-center justify-center">
            <User size={16} />
          </div>
          <div>
            <p className="font-semibold">{lead?.name || "Unknown Lead"}</p>
            <p className="text-xs text-gray-500">Inbound Call</p>
          </div>
        </div>

        <InfoRow icon={<Phone size={14} />} label="Phone" value={lead?.phone_number || "N/A"} />
        <InfoRow icon={<Mail size={14} />} label="Email" value={lead?.email || "N/A"} />
        <InfoRow icon={<Briefcase size={14} />} label="Business" value={lead?.business_desc || "N/A"} />
      </div>

      <div className="bg-white border rounded-lg">
        <div className="flex gap-2 px-4 py-3 border-b">
          <FileText size={14} />
          <p className="font-semibold text-sm">Call Summary</p>
        </div>
        <div className="px-4 py-3 space-y-2 text-sm">
          <SummaryRow icon={<Clock size={14} />} label="Duration" value="3m 49s" />
          <SummaryRow icon={<PhoneCall size={14} />} label="Outcome" value="No Response" />
          <p className="text-xs text-gray-500">
            User did not respond clearly. No lead qualification captured.
          </p>
        </div>
      </div>
    </div>
  );
}

/* HELPERS */

function InfoRow({ icon, label, value }: any) {
  return (
    <div className="flex gap-3 px-4 py-2 text-sm">
      <div className="text-gray-400">{icon}</div>
      <div>
        <p className="text-[11px] text-gray-500">{label}</p>
        <p className="truncate">{value}</p>
      </div>
    </div>
  );
}

function SummaryRow({ icon, label, value }: any) {
  return (
    <div className="flex justify-between text-sm">
      <span className="flex gap-2 text-gray-500">
        {icon} {label}
      </span>
      <span className="font-medium">{value}</span>
    </div>
  );
}

import { motion } from "framer-motion";
import {
  MessageSquare,
  DollarSign,
  Users,
  Activity,
  ArrowUpRight,
  ArrowDownRight,
  Calendar,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import { kpiAPI } from "@/api/kpi";
import type {
  KpiSummary,
  KpiTimeseriesPoint,
} from "@/types/conversation.types";

import { CostOverTimeChart } from "@/components/charts/CostOverTimeChart";
import { ConversationsPerDayChart } from "@/components/charts/ConversationsPerDayChart";
import { AvgCallDurationChart } from "@/components/charts/AvgCallDurationChart";

/* ================= TYPES & HELPERS ================= */

type Preset = "7d" | "15d" | "30d" | "all" | "custom";

const formatUsd = (v = 0) => `$${v.toFixed(2)}`;

const getRangeFromPreset = (preset: Preset) => {
  const end = new Date();
  const start = new Date();

  if (preset === "all") {
    start.setFullYear(2000);
  } else if (preset === "7d") {
    start.setDate(end.getDate() - 6);
  } else if (preset === "15d") {
    start.setDate(end.getDate() - 14);
  } else if (preset === "30d") {
    start.setDate(end.getDate() - 29);
  }

  return {
    from: start.toISOString().slice(0, 10),
    to: end.toISOString().slice(0, 10),
  };
};

const container = {
  hidden: { opacity: 0 },
  show: { opacity: 1, transition: { staggerChildren: 0.08 } },
};

const item = {
  hidden: { opacity: 0, y: 16 },
  show: { opacity: 1, y: 0 },
};

/* ================= HOME PAGE ================= */

export function HomePage() {
  const [kpis, setKpis] = useState<KpiSummary | null>(null);
  const [timeseries, setTimeseries] = useState<KpiTimeseriesPoint[]>([]);
  const [loading, setLoading] = useState(true);

  /* ===== GLOBAL DATE RANGE ===== */
  const [preset, setPreset] = useState<Preset>("7d");
  const [{ from, to }, setRange] = useState(() =>
    getRangeFromPreset("7d")
  );

  useEffect(() => {
    kpiAPI
      .getKpis()
      .then((res) => {
        setKpis(res.summary);
        setTimeseries(res.timeseries);
      })
      .catch(console.error)
      .finally(() => setLoading(false));
  }, []);

  const handlePresetChange = (p: Preset) => {
    setPreset(p);
    if (p !== "custom") {
      setRange(getRangeFromPreset(p));
    }
  };

  const handleDateChange = (f: string, t: string) => {
    setPreset("custom");
    setRange({ from: f, to: t });
  };

  /* ===== FILTER DATA ONCE ===== */
  const filteredData = useMemo(() => {
    return timeseries
      .filter((p) => {
        const d = new Date(p.date).toISOString().slice(0, 10);
        return d >= from && d <= to;
      })
      .sort(
        (a, b) =>
          new Date(a.date).getTime() -
          new Date(b.date).getTime()
      ); // ≡ƒæê IMPORTANT
  }, [timeseries, from, to]);

  const previousFilteredData = useMemo(() => {
    if (preset === "all") return [];

    const fromDate = new Date(from);
    const toDate = new Date(to);
    const durationDays = Math.round((toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24)) + 1;

    const prevToDate = new Date(fromDate);
    prevToDate.setDate(prevToDate.getDate() - 1);

    const prevFromDate = new Date(prevToDate);
    prevFromDate.setDate(prevFromDate.getDate() - durationDays + 1);

    const prevFrom = prevFromDate.toISOString().slice(0, 10);
    const prevTo = prevToDate.toISOString().slice(0, 10);

    return timeseries.filter((p) => {
      const d = new Date(p.date).toISOString().slice(0, 10);
      return d >= prevFrom && d <= prevTo;
    });
  }, [timeseries, from, to, preset]);

  const computeMetrics = (data: KpiTimeseriesPoint[]) => {
    const totalConversations = data.reduce((sum, p) => sum + p.conversations, 0);
    const totalCost = data.reduce((sum, p) => sum + p.cost_usd, 0);
    const totalMessages = data.reduce((sum, p) => sum + p.messages, 0);
    const avgCost = totalConversations > 0 ? totalCost / totalConversations : 0;
    return {
      conversations: totalConversations,
      cost: totalCost,
      messages: totalMessages,
      avgCost: avgCost
    };
  };

  const currentMetrics = useMemo(() => computeMetrics(filteredData), [filteredData]);
  const previousMetrics = useMemo(() => computeMetrics(previousFilteredData), [previousFilteredData]);

  const calculateTrend = (current: number, previous: number) => {
    if (previous === 0) return { text: current > 0 ? "+100%" : "0%", up: current >= 0 };
    const diff = ((current - previous) / previous) * 100;
    return {
      text: `${diff > 0 ? '+' : ''}${diff.toFixed(1)}%`,
      up: diff >= 0,
    };
  };

  const getTrendObj = (key: keyof ReturnType<typeof computeMetrics>) => {
    if (preset === "all") return null;
    return calculateTrend(currentMetrics[key], previousMetrics[key]);
  };

  /* ===== KPI CARDS ===== */
  const stats = [
    {
      label: "Total Conversations",
      value: loading ? "ΓÇö" : currentMetrics.conversations,
      icon: MessageSquare,
      trendObj: getTrendObj("conversations"),
    },
    {
      label: "Total Cost",
      value: loading
        ? "ΓÇö"
        : formatUsd(currentMetrics.cost),
      icon: DollarSign,
      trendObj: getTrendObj("cost"),
    },
    {
      label: "Total Messages",
      value: loading
        ? "ΓÇö"
        : currentMetrics.messages.toLocaleString(),
      icon: Activity,
      trendObj: getTrendObj("messages"),
    },
    {
      label: "Avg Cost / Conv",
      value: loading
        ? "ΓÇö"
        : formatUsd(currentMetrics.avgCost),
      icon: Users,
      trendObj: getTrendObj("avgCost"),
    },
  ];

  return (
    <motion.div
      variants={container}
      initial="hidden"
      animate="show"
      className="space-y-10"
    >
      {/* ================= HEADER ================= */}
      <div>
        <h1 className="text-3xl font-bold text-slate-900">
          Dashboard Overview
        </h1>
        <p className="text-slate-500">
          Welcome back! HereΓÇÖs your activity summary.
        </p>
      </div>

      {/* ================= KPI CARDS ================= */}
      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4">
        {stats.map((stat) => (
          <motion.div
            key={stat.label}
            variants={item}
            className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"
          >
            <div className="flex items-start justify-between">
              <stat.icon className="h-6 w-6 text-slate-700" />
              {stat.trendObj && (
                <div
                  className={`flex items-center gap-1 text-xs font-medium ${stat.trendObj.up ? "text-green-600" : "text-red-600"
                    }`}
                >
                  {stat.trendObj.text}
                  {stat.trendObj.up ? (
                    <ArrowUpRight size={14} />
                  ) : (
                    <ArrowDownRight size={14} />
                  )}
                </div>
              )}
            </div>

            <div className="mt-4">
              <p className="text-sm text-slate-500">
                {stat.label}
              </p>
              <p className="mt-1 text-2xl font-bold text-slate-900">
                {stat.value}
              </p>
            </div>
          </motion.div>
        ))}
      </div>

      {/* ================= ANALYTICS CONTROLS ================= */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <h2 className="text-lg font-semibold text-slate-900">
          Analytics
        </h2>

        <div className="flex items-center gap-3 rounded-xl border border-slate-200 bg-white p-3 shadow-sm">
          {(["all", "7d", "15d", "30d"] as Preset[]).map((p) => (
            <button
              key={p}
              onClick={() => handlePresetChange(p)}
              className={`rounded-md px-3 py-1 text-xs font-medium ${preset === p
                  ? "bg-indigo-600 text-white"
                  : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                }`}
            >
              {p === "30d" ? "1M" : p === "all" ? "ALL" : p.toUpperCase()}
            </button>
          ))}

          <Calendar size={14} className="text-slate-500" />

          <input
            type="date"
            value={from}
            onChange={(e) =>
              handleDateChange(e.target.value, to)
            }
            className="rounded-md border border-slate-200 px-2 py-1 text-xs"
          />

          <input
            type="date"
            value={to}
            onChange={(e) =>
              handleDateChange(from, e.target.value)
            }
            className="rounded-md border border-slate-200 px-2 py-1 text-xs"
          />
        </div>
      </div>

      {/* ================= CHARTS ================= */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        <CostOverTimeChart data={filteredData} />
        <ConversationsPerDayChart data={filteredData} />
      </div>

      <AvgCallDurationChart data={filteredData} />
    </motion.div>
  );
}

